"""Evaluate the frozen top-three relative-strength plus breadth false-breakout filter."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import pandas as pd
from experiments.evaluate_sector_trend_detector import encode,evaluate_etfs,trading_summary
def detection_summary(labels,positions):
 labels=labels.copy();labels["year"]=labels.trend_start.dt.year;positions=positions.copy();positions["year"]=positions.entry_signal_date.dt.year;historical=labels[labels.year.between(2018,2025)];signals=positions[positions.year.between(2018,2025)];matched=set(historical.loc[historical.detected,"position_id"]);precision=float(signals.position_id.isin(matched).mean()) if len(signals) else 0.0;periods={}
 for name,a,b in [("2018-2022",2018,2022),("2023-2024",2023,2024),("2025",2025,2025),("2026",2026,2026)]:
  trends=labels[labels.year.between(a,b)];p=positions[positions.year.between(a,b)];ids=set(trends.loc[trends.detected,"position_id"]);periods[name]={"trend_count":len(trends),"signal_count":len(p),"recall":float(trends.detected.mean()) if len(trends) else 0.0,"precision":float(p.position_id.isin(ids).mean()) if len(p) else 0.0}
 summary={"trend_labels":len(historical),"detected":int(historical.detected.sum()),"recall":float(historical.detected.mean()),"signals":len(signals),"precision":precision,"false_positive_rate":1-precision,"median_delay":float(historical.loc[historical.detected,"detection_delay"].median()) if historical.detected.any() else None,"median_capture_ratio":float(historical.loc[historical.detected,"capture_ratio"].median()) if historical.detected.any() else None,"periods":periods};checks={"signals":len(signals)>=30,"precision":precision>=.60,"validation_precision":periods["2023-2024"]["precision"]>=.55,"holdout_precision":periods["2025"]["precision"]>=.55,"recall":summary["recall"]>=.30,"delay":summary["median_delay"]<=7,"capture":summary["median_capture_ratio"]>=.50};return summary,checks
def run(labels_path,positions_path,candidates,daily,adj,benchmark,events_path,out_json,out_md):
 labels=pd.read_csv(labels_path);labels["trend_start"]=pd.to_datetime(labels.trend_start);labels["detected"]=labels.detected.astype(str).str.lower().eq("true");positions=pd.read_csv(positions_path);positions["entry_signal_date"]=pd.to_datetime(positions.entry_signal_date);positions["exit_signal_date"]=pd.to_datetime(positions.exit_signal_date,errors="coerce");detection,dchecks=detection_summary(labels,positions);events=evaluate_etfs(positions,candidates,daily,adj,benchmark);events.to_csv(events_path,index=False);trading,tchecks=trading_summary(events);payload={"study":"a-share-sector-false-breakout-filter-v2","authority":"exploratory_only_no_platform_prepare_operation","detection":{"summary":detection,"checks":dchecks,"verdict":"GO" if all(dchecks.values()) else "NO-GO"},"trading":{"summary":trading,"checks":tchecks,"verdict":"GO" if all(tchecks.values()) else "NO-GO"},"events":events_path};Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2,default=encode)+"\n");lines=["# A股行业假突破过滤V2结果","",f"- detection: **{payload['detection']['verdict']}**",f"- trading: **{payload['trading']['verdict']}**",f"- signals/precision/recall/delay/capture: {detection['signals']} / {detection['precision']:.2%} / {detection['recall']:.2%} / {detection['median_delay']:.1f} / {detection['median_capture_ratio']:.2%}",f"- ETF complete/positive20/outperform20/median active20: {trading['complete_events']} / {trading['absolute_positive20']:.2%} / {trading['outperform20']:.2%} / {trading['median_active20']:.2%}"];Path(out_md).write_text("\n".join(lines)+"\n");print("\n".join(lines));return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--labels",default="overall/a-share-sector-leader-breadth-labels.csv");p.add_argument("--positions",default="overall/a-share-sector-leader-breadth-positions.csv");p.add_argument("--candidates",default="overall/a-share-sector-etf-candidates.csv");p.add_argument("--daily",default="overall/a-share-sector-etf-raw-v2/fund_daily.parquet");p.add_argument("--adj",default="overall/a-share-sector-etf-raw-v2/fund_adj.parquet");p.add_argument("--benchmark",default="overall/a-share-equity-etf-daily-current.csv");p.add_argument("--events",default="overall/a-share-sector-false-breakout-etf-events.csv");p.add_argument("--out-json",default="overall/a-share-sector-false-breakout-filter-v2-result.json");p.add_argument("--out-md",default="overall/a-share-sector-false-breakout-filter-v2-result.md");a=p.parse_args(argv);run(a.labels,a.positions,a.candidates,a.daily,a.adj,a.benchmark,a.events,a.out_json,a.out_md);return 0
if __name__=="__main__":raise SystemExit(main())
